import { Duration } from "./src/luxon.js";

if (typeof Duration?.fromObject !== "function") {
  process.exitCode = 125;
} else {
  const dur = Duration.fromObject({ hours: 96, minutes: 0, seconds: -10 });
  if (typeof dur.normalize !== "function") {
    process.exitCode = 125;
  } else {
    const got = dur.normalize().toObject();
    const expected = { hours: 95, minutes: 59, seconds: 50 };
    if (JSON.stringify(got) !== JSON.stringify(expected)) {
      console.log(
        `WHOBROKEIT_BUG: expected normalize() to give ${JSON.stringify(expected)} but got ${JSON.stringify(got)}`
      );
      process.exitCode = 1;
    } else {
      process.exitCode = 0;
    }
  }
}
